python3 - <<'PY'
import json
rows=[json.loads(l) for l in open('/workspace/logs/host_memory.jsonl')]
for r in rows:
    t=r['time']-1793082211.18
    if 176 <= t <= 191:
        st=r['cgroup']['memory.stat']
        def f(k):
            for line in st.split('\n'):
                if line.startswith(k+' '): return int(line.split()[1])
        print(round(t,2), 'cur', round(int(r['cgroup']['memory.current'])/1e9,3), 'anon', round(f('anon')/1e9,3), 'file', round(f('file')/1e9,3), 'dirty', f('file_dirty'))
PY

