import json
rows=[json.loads(l) for l in open('/workspace/logs/host_memory.jsonl')]
prev=None
for r in rows:
    t=r['time']-rows[0]['time']
    st=r['cgroup']['memory.stat']
    def f(k):
        for line in st.split('\n'):
            if line.startswith(k+' '): return int(line.split()[1])
    a=f('anon')/1e9
    if prev is None or abs(a-prev)>0.5:
        print(round(t,1), 'cur', round(int(r['cgroup']['memory.current'])/1e9,2), 'anon', round(a,2))
    prev=a
PY

