import json
rows=[json.loads(l) for l in open('/workspace/logs/host_memory.jsonl')]
prev=None
t0=rows[0]['time']
for r in rows:
    st=r['cgroup']['memory.stat']
    def f(k):
        for line in st.split('\n'):
            if line.startswith(k+' '): return int(line.split()[1])
    s=f('shmem')/1e9; a=f('anon')/1e9
    if prev is None or abs(s-prev)>0.2:
        print(round(r['time']-t0,1), 'shmem', round(s,3), 'anon', round(a,3), 'cur', round(int(r['cgroup']['memory.current'])/1e9,2), 'max', r['cgroup']['memory.events'].split('max ')[1].split('\n')[0])
    prev=s
PY

